#include "service/CanvasBrokerOperations.hpp"
#include "TestSupport.hpp"
using Json=nlohmann::json;
void operations(){
 const Json shape{{"kind","shape"},{"shapeType","rectangle"},{"x",0},{"y",0},{"width",1},{"height",1},{"permission","writers"}};
 std::map<std::string,Json> store{{"box",shape}};
 auto read=[&](const std::string& id)->std::optional<Json>{return store.count(id)?std::optional<Json>(store[id]):std::nullopt;};
 auto run=[&](Json ops){return agora::broker::prepare(ops,read,{"writers"},false);};
 auto reject=[&](Json ops){bool rejected=false;try{run(ops);}catch(const std::invalid_argument&){rejected=true;}AGORA_CHECK(rejected);};
 const std::unordered_set<std::string> all_roles{"writers","readers","disabled"},read_roles{"writers","readers"},write_roles{"writers"};
 auto multi=shape;multi["permission"]=Json::array({"writers","readers","disabled"});
 auto shared=agora::broker::prepare(Json::array({{{"action","create"},{"id","shared"},{"patch",multi}}}),read,write_roles,false,&read_roles,nullptr,&all_roles);
 AGORA_CHECK(queryCanAccess(shared.items["shared"],{"readers"},false)&&!queryCanAccess(shared.items["shared"],{"disjoint"},false));
 auto automatic=shape;automatic.erase("permission");auto inferred=agora::broker::prepare(Json::array({{{"action","create"},{"id","automatic"},{"patch",automatic}}}),read,write_roles,false,&read_roles,nullptr,&all_roles);
 AGORA_CHECK(queryPermissionGroups(inferred.items["automatic"])==all_roles);
 bool forged=false;multi["permission"].push_back("outsider");try{agora::broker::prepare(Json::array({{{"action","create"},{"id","forged"},{"patch",multi}}}),read,write_roles,false,&read_roles,nullptr,&all_roles);}catch(const std::invalid_argument& e){forged=std::string(e.what())=="ITEM_PERMISSION_DENIED";}AGORA_CHECK(forged);
 auto created=run(Json::array({{{"action","create"},{"id","new"},{"patch",shape}}}));
 AGORA_CHECK(created.items["new"]==shape&&created.expected["new"]==-1);
 auto lock=run(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"locked",true}}}}}));
 AGORA_CHECK(lock.items["box"]["locked"]==true);
 store["box"]=lock.items["box"];
 reject(Json::array({{{"action","translate"},{"ids",Json::array({"box"})},{"dx",1},{"dy",0}}}));
 reject(Json::array({{{"action","delete"},{"id","box"}}}));
 reject(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"color","blue"}}}}}));
 reject(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"locked",false},{"x",2}}}}}));
 reject(Json::array({{{"action","patch"},{"id","box"},{"patch",Json::object()},{"unset",Json::array({"locked"})}}}));
 auto unlock=run(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"locked",false}}}}}));AGORA_CHECK(unlock.items["box"]["locked"]==false);
 bool admin_denied=false;try{agora::broker::prepare(Json::array({{{"action","delete"},{"id","box"}}}),read,{},true);}catch(const std::invalid_argument& e){admin_denied=std::string(e.what())=="ITEM_LOCKED";}AGORA_CHECK(admin_denied);
 store["box"]=shape;
 auto bad_lock=shape;bad_lock["locked"]="true";reject(Json::array({{{"action","create"},{"id","bad-lock"},{"patch",bad_lock}}}));
 auto locked_stroke=Json{{"kind","stroke"},{"permission","writers"},{"points",Json::array({{{"x",0},{"y",0}},{{"x",1},{"y",1}}})},{"locked",true}};
 store["stroke-lock"]=locked_stroke;reject(Json::array({{{"action","delete"},{"id","stroke-lock"}}}));
 auto unchanged=store;reject(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"x",3}}}},{{"action","delete"},{"id","stroke-lock"}}}));AGORA_CHECK(store==unchanged);
 store.erase("stroke-lock");
 const Json chart{{"kind","chart"},{"chartType","bar"},{"columns",Json::array({"label","value"})},{"rows",Json::array({Json::array({"A","12"})})},{"x",0},{"y",0},{"width",1},{"height",1},{"permission","writers"}};
 auto chart_created=run(Json::array({{{"action","create"},{"id","chart"},{"patch",chart}}}));AGORA_CHECK(chart_created.items["chart"]==chart);
 auto bad_chart=chart;bad_chart["chartType"]="invalid";reject(Json::array({{{"action","create"},{"id","badchart"},{"patch",bad_chart}}}));
 bad_chart=chart;bad_chart["rows"]=Json::array({Json::array({"only one"})});reject(Json::array({{{"action","create"},{"id","badchart"},{"patch",bad_chart}}}));
 auto volume=shape;volume["shapeType"]="volume-cube";volume["volumeStyle"]="wireframe";auto volume_created=run(Json::array({{{"action","create"},{"id","volume"},{"patch",volume}}}));AGORA_CHECK(volume_created.items["volume"]==volume);
 volume["volumeStyle"]="invalid";reject(Json::array({{{"action","create"},{"id","volume"},{"patch",volume}}}));
 auto moved=run(Json::array({{{"action","translate"},{"ids",Json::array({"box"})},{"dx",3},{"dy",4},{"start",{{"x",0},{"y",0}}},{"end",{{"x",3},{"y",4}}}}}));
 AGORA_CHECK(moved.translations[0]["start"]["x"]==0&&moved.translations[0]["end"]["y"]==4);
 reject(Json::array({{{"action","translate"},{"ids",Json::array({"box"})},{"dx",3},{"dy",4},{"start",{{"x",0},{"y",0}}},{"end",{{"x",9},{"y",4}}}}}));
 AGORA_CHECK(moved.items["box"]["x"]==3&&moved.items["box"]["y"]==4&&moved.only_translations);
 AGORA_CHECK(store["box"]==shape);
 auto patched=run(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"color","red"}}}}}));
 AGORA_CHECK(patched.items["box"]["color"]=="red"&&!patched.only_translations);
 auto removed=run(Json::array({{{"action","delete"},{"id","box"}}}));AGORA_CHECK(removed.items["box"].is_null());
 auto value=Json{{"kind","value"},{"title",""},{"valueType","real"},{"valueMin",0},{"valueMax",1},{"valueStep",0.01},{"valueNumber",0.25},{"valueText",""},{"valueOptions",Json::array({"A","B"})},{"x",0},{"y",0},{"width",0.28},{"height",0.21},{"permission","writers"}};
 AGORA_CHECK(run(Json::array({{{"action","create"},{"id","value"},{"patch",value}}})).items["value"]["valueNumber"]==0.25);
 auto invalid_value=value;invalid_value["valueNumber"]=2;reject(Json::array({{{"action","create"},{"id","bad-value"},{"patch",invalid_value}}}));
 invalid_value=value;invalid_value["valueType"]="integer";invalid_value["valueStep"]=1;reject(Json::array({{{"action","create"},{"id","bad-integer"},{"patch",invalid_value}}}));
 auto code=Json{{"kind","text"},{"renderMode","code"},{"text","print(1)"},{"locked",true},{"permission","writers"}};store["status-code"]=code;
 Json runtime={{"running",true},{"status","running"},{"updatedAt",123}};const std::unordered_set<std::string> executors{"writers"},none;
 auto status=agora::broker::prepare(Json::array({{{"action","patch"},{"id","status-code"},{"patch",{{"runtimeState",runtime}}}}}),read,none,false,&executors,&executors,&executors);
 AGORA_CHECK(status.items["status-code"]["locked"]==true&&status.items["status-code"]["runtimeState"]["status"]=="running");
 reject(Json::array({{{"action","patch"},{"id","status-code"},{"patch",{{"runtimeState",runtime},{"text","changed"}}}}}));
 auto executor=shape; executor["runtimeRole"]="executor";
 auto accepted=run(Json::array({{{"action","create"},{"id","executor"},{"patch",executor}}}));
 AGORA_CHECK(accepted.items["executor"]["runtimeRole"]=="executor");
 auto terminal=shape;terminal["runtimeRole"]="terminal";
 auto connected=run(Json::array({{{"action","create"},{"id","terminal"},{"patch",terminal}}}));
 AGORA_CHECK(connected.items["terminal"]["runtimeRole"]=="terminal");
 auto output=shape;output["runtimeRole"]="output";
 output["runtimeResults"]=Json::array({{{"runId","run-1"},{"codeId","code-1"},{"createdAt",123},{"exitCode",0},{"output","hello\n"},{"timedOut",false},{"truncated",false}}});
 auto saved=run(Json::array({{{"action","create"},{"id","result"},{"patch",output}}}));
 AGORA_CHECK(saved.items["result"]["runtimeResults"][0]["output"]=="hello\n");
 output["runtimeResults"][0]["unknown"]=true;
 reject(Json::array({{{"action","create"},{"id","bad-result"},{"patch",output}}}));
 output["runtimeResults"][0].erase("unknown");
 executor["runtimeRole"]="arbitrary";
 reject(Json::array({{{"action","create"},{"id","invalid-role"},{"patch",executor}}}));
 reject(Json::array({{{"action","create"},{"id","box"},{"patch",shape}}}));
 reject(Json::array({{{"action","patch"},{"id","missing"},{"patch",{{"x",1}}}}}));
 reject(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"permission","admins"}}}}}));
 reject(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"__broker_revision",1}}}}}));
 reject(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"bendPoints",Json::array({{{"x",1},{"y",1}}})},{"bendPointCount",3}}}}}));
 reject(Json::array({{{"action","translate"},{"ids",Json::array({"box","box"})},{"dx",1},{"dy",1}}}));
 Json connector{{"kind","connector"},{"from","box"},{"to","new"},{"permission","writers"}};
 auto graph=run(Json::array({{{"action","create"},{"id","wire"},{"patch",connector}},{{"action","create"},{"id","new"},{"patch",shape}}}));
 AGORA_CHECK(graph.items.size()==2);
 reject(Json::array({{{"action","create"},{"id","wire"},{"patch",connector}}}));
 Json text{{"kind","text"},{"text","a"},{"permission","writers"},{"automerge_snapshot","base"},{"automerge_changes",Json::array({{{"field","text"},{"change","a"}}})}};
 store["text"]=text;
 auto merged=run(Json::array({{{"action","patch"},{"id","text"},{"patch",{{"text","b"},{"automerge_snapshot","other"},{"automerge_changes",Json::array({{{"field","text"},{"change","b"}}})}}}}}));
 AGORA_CHECK(merged.items["text"]["automerge_snapshot"]=="base"&&merged.items["text"]["automerge_changes"].size()==2);
 auto plain=run(Json::array({{{"action","create"},{"id","plain"},{"patch",{{"kind","note"},{"text","Python-created"},{"permission","writers"}}}}}));
 AGORA_CHECK(plain.items["plain"]["text"]=="Python-created"&&!plain.items["plain"].contains("automerge_snapshot"));
 auto replacement=run(Json::array({{{"action","patch"},{"id","text"},{"patch",{{"text","replacement"}}},{"unset",Json::array({"automerge_snapshot","automerge_changes"})}}}));
 AGORA_CHECK(replacement.items["text"]["text"]=="replacement"&&!replacement.items["text"].contains("automerge_snapshot")&&!replacement.items["text"].contains("automerge_changes"));
 auto malformed=text;malformed.erase("automerge_snapshot");reject(Json::array({{{"action","create"},{"id","malformed"},{"patch",malformed}}}));
 const std::unordered_set<std::string> no_writes,readable{"writers"},executable{"writers"};
 auto denied_readonly=[&](Json ops){bool denied=false;try{agora::broker::prepare(ops,read,no_writes,false,&readable,&executable);}catch(const std::invalid_argument&){denied=true;}AGORA_CHECK(denied);};
 denied_readonly(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"x",4}}}}}));
 denied_readonly(Json::array({{{"action","delete"},{"id","box"}}}));
 denied_readonly(Json::array({{{"action","create"},{"id","readonly-create"},{"patch",shape}}}));
 denied_readonly(Json::array({{{"action","translate"},{"ids",Json::array({"box"})},{"dx",1},{"dy",0}}}));
 store["output"]=output;
 auto output_result=agora::broker::prepare(Json::array({{{"action","patch"},{"id","output"},{"patch",{{"runtimeResults",output["runtimeResults"]}}}}}),read,no_writes,false,&readable,&executable);
 AGORA_CHECK(output_result.items["output"]["runtimeResults"]==output["runtimeResults"]);
 denied_readonly(Json::array({{{"action","patch"},{"id","output"},{"patch",{{"runtimeResults",output["runtimeResults"]},{"x",3}}}}}));
 bool no_execute_denied=false;try{agora::broker::prepare(Json::array({{{"action","patch"},{"id","output"},{"patch",{{"runtimeResults",output["runtimeResults"]}}}}}),read,readable,false,&readable,&no_writes);}catch(const std::invalid_argument&){no_execute_denied=true;}AGORA_CHECK(no_execute_denied);
 Json notebook{{"kind","shape"},{"shapeType","rectangle"},{"runtimeRole","notebook"},{"permission","writers"},{"locked",true},{"notebookCells",Json::array({{{"id","cell1"},{"cellType","code"},{"source","x=1"}}})},{"notebookResults",Json::object()}};
 agora::broker::validate(notebook);store["notebook"]=notebook;
 auto notebook_output=agora::broker::prepare(Json::array({{{"action","patch"},{"id","notebook"},{"patch",{{"notebookResults",{{"cell1",{{"outputs",Json::array({{{"output_type","stream"},{"text","1"}}})},{"executionCount",1},{"exitCode",0}}}}}}}}}),read,no_writes,false,&readable,&executable);
 AGORA_CHECK(notebook_output.items["notebook"]["notebookResults"]["cell1"]["executionCount"]==1);
 denied_readonly(Json::array({{{"action","patch"},{"id","notebook"},{"patch",{{"notebookCells",Json::array()}}}}}));
 auto bad_notebook=notebook;bad_notebook["notebookCells"].push_back(bad_notebook["notebookCells"][0]);bool duplicate_denied=false;try{agora::broker::validate(bad_notebook);}catch(const std::invalid_argument&){duplicate_denied=true;}AGORA_CHECK(duplicate_denied);
 store["box"]["__host_version"]=Json::array({1,2});store["box"]["__broker_revision"]=7;
 auto migrated=run(Json::array({{{"action","patch"},{"id","box"},{"patch",{{"x",2}}}}}));
 AGORA_CHECK(!migrated.items["box"].contains("__host_version")&&migrated.expected["box"]==7);
}
int main(){return runTest("server authoritative operations, ACL, graph and CRDT union",operations);}
